# Reproduces captures/supporting.txt (read-only commands on gitignored files generated by j2gha for example 000).
# Run from the repo root:  nx capture local docs/video/000-ch2-analyse-convert-validate/captures/supporting.txt docs/video/000-ch2-analyse-convert-validate/captures/supporting.sh
# Step 0 picks three columns of the findings table: the full rows contain emoji (no emoji font here) and wrap badly.
step "sed -n '86,99p' examples/000/RESULTS.md | awk -F'|' 'NR>=5 {printf \"%-22s %-5s %s\\n\", \$3, \$4, \$5}'"
step 'grep -nE "^  [a-z-]+:$" examples/000/gha/workflow.yml | tail -9'
step "grep -n -B2 'endsWith' examples/000/gha/workflow.yml"
step "grep -E '^- \*\*(Classification|Automated)' examples/000/gha/migration-report.md"
step "grep -n 'J2GHA_TODO' examples/000/gha/workflow.yml"
